import {EMPTY, STORE_VERSION,uid,safeText,safeUrl,isoTime,finite,parseCSV,importProducts,importMetrics,commissionTHB,isRecent,productIssues,canCampaign,rankProducts,chooseProduct,createCampaign,todayBangkok,mergeByKey,exportCSV,productTemplate,metricsTemplate} from './logic.js';
const $=(s)=>document.querySelector(s),$$=(s)=>Array.from(document.querySelectorAll(s));
const escapeHTML=(x)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,unit='')=>n===null||n===undefined||!Number.isFinite(Number(n))?'—':new Intl.NumberFormat('th-TH',{maximumFractionDigits:2}).format(n)+(unit?` ${unit}`:'');
const dt=(iso)=>iso?new Date(iso).toLocaleString('th-TH',{timeZone:'Asia/Bangkok',dateStyle:'medium',timeStyle:'short'}):'ไม่ระบุ';
const urlLink=(link,label='เปิดต้นทาง')=>link?`<a href="${escapeHTML(link)}" target="_blank" rel="noopener noreferrer">↗ ${escapeHTML(label)}</a>`:'<span class="muted">ไม่มีหลักฐาน URL</span>';
const showAlert=(m,error=false)=>{const old=$('.toast');if(old)old.remove();const el=document.createElement('div');el.className=`toast ${error?'error':''}`;el.textContent=m;document.body.append(el);setTimeout(()=>el.remove(),4200)};
const CONFIG=window.KEN_CONFIG||{};const AUTH_CONFIGURED=Boolean(CONFIG.supabaseUrl&&CONFIG.supabasePublishableKey);const APP_VERSION='7.0';
let gmailToken=null,gmailTokenUntil=0,gmailHeaders=[],aiBusy=false,aiIdea=null;
let emailSentTo='';let emailBusy=false;let selectedCharacterId=null;let sb=null,currentUser=null,state=EMPTY(),tab=new URLSearchParams(location.search).get('tab')||'start',selectedProduct=null,selectedCampaign=null,editingCharacter=null,report={products:null,metrics:null},signedImages={},saveQueue=Promise.resolve(),saveStatus='';
const validTabs=new Set(['ai','gmail','start','overview','hunter','products','characters','autopilot','campaigns','metrics','connections','audit','settings']);if(!validTabs.has(tab))tab='start';if(tab==='overview')tab='start';
const nav=[['ai','✦','AI คิดให้ทั้งหมด'],['start','▸','เริ่มทำคลิป'],['products','▤','คลังสินค้า'],['characters','◉','ตัวละคร'],['campaigns','▣','คลิปของฉัน'],['gmail','✉','เชื่อม Gmail']];const advancedNav=[['hunter','⌕','จัดอันดับสินค้า'],['autopilot','⚡','ตั้งค่าแคมเปญ'],['metrics','▥','สถิติ'],['connections','⌁','เชื่อมบัญชี'],['audit','◎','ประวัติข้อมูล'],['settings','⚙','ตั้งค่า'],['overview','▦','Dashboard เดิม']];
