const storageKey=()=>`ken-affiliate-v4:${currentUser?.id||'local'}`;
function normalizeState(x){if(!x||x.version!==STORE_VERSION)throw new Error('ไฟล์สำรองไม่ใช่รูปแบบ v4');const blank=EMPTY();return {...blank,...x,products:Array.isArray(x.products)?x.products:[],characters:Array.isArray(x.characters)?x.characters:[],campaigns:Array.isArray(x.campaigns)?x.campaigns:[],metrics:Array.isArray(x.metrics)?x.metrics:[],posts:Array.isArray(x.posts)?x.posts:[],audit:Array.isArray(x.audit)?x.audit:[],settings:{...blank.settings,...x.settings}}}
function persist(){
 state.version=STORE_VERSION;state.audit=state.audit.slice(0,130);
 if(!sb||!currentUser){try{localStorage.setItem(storageKey(),JSON.stringify(state));saveStatus='บันทึกในเบราว์เซอร์นี้'}catch{saveStatus='พื้นที่เก็บข้อมูลเต็ม';showAlert('บันทึกข้อมูลไม่สำเร็จ อาจเป็นเพราะรูปภาพขนาดใหญ่',true)}return}
 const snapshot=structuredClone(state);saveStatus='กำลัง Sync';
 saveQueue=saveQueue.then(async()=>{const {error}=await sb.from('workspace_data').upsert({user_id:currentUser.id,data:snapshot,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error;saveStatus='Sync สำเร็จ';const tag=$('#syncLabel');if(tag)tag.textContent=saveStatus}).catch(err=>{saveStatus='Sync ไม่สำเร็จ';showAlert('บันทึกขึ้น Supabase ไม่สำเร็จ: '+err.message,true)});
}
function commit(action,message){audit(action,message);persist();render()}
function navigate(next){if(!validTabs.has(next))return;tab=next;selectedCampaign=null;const url=new URL(location.href);url.searchParams.set('tab',tab);history.replaceState({},'',url);render();window.scrollTo({top:0,behavior:'smooth'})}
function downloadText(text,filename,type='text/csv;charset=utf-8'){const blob=new Blob(['\ufeff',text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function initialize(){
 if(AUTH_CONFIGURED){try{
  await new Promise((resolve,reject)=>{if(window.supabase)return resolve();const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.117.3/dist/umd/supabase.min.js';sc.onload=resolve;sc.onerror=()=>reject(new Error('โหลด Supabase SDK ไม่ได้'));document.head.append(sc)});
  sb=window.supabase.createClient(CONFIG.supabaseUrl,CONFIG.supabasePublishableKey,{auth:{flowType:'implicit',detectSessionInUrl:true,autoRefreshToken:true,persistSession:true}});
  const {data:{session},error}=await sb.auth.getSession();if(error)throw error;if(session?.user)await loadUser(session.user);
  sb.auth.onAuthStateChange(async(evt,session)=>{if(evt==='SIGNED_IN'&&session?.user?.id!==currentUser?.id)await loadUser(session.user);if(evt==='SIGNED_OUT'){currentUser=null;gmailToken=null;gmailTokenUntil=0;gmailHeaders=[];emailSentTo='';state=EMPTY();render()}});
 }catch(e){document.querySelector('#app').innerHTML=`<div class="authscreen"><div class="authpanel"><h1>เชื่อมระบบล็อกอินไม่ได้</h1><p class="muted">${escapeHTML(e.message)}</p><p>ตรวจสอบค่า public config, URL และเครือข่าย</p><button class="btn secondary" onclick="location.reload()">ลองอีกครั้ง</button></div></div>`;return}}
 else {try{state=normalizeState(JSON.parse(localStorage.getItem(storageKey())))}catch{state=EMPTY()}}
 render();
}
async function loadUser(user){currentUser=user;state=EMPTY();renderLoading();const {data,error}=await sb.from('workspace_data').select('data').eq('user_id',user.id).maybeSingle();if(error){saveStatus='อ่านฐานข้อมูลไม่สำเร็จ';showAlert('ไม่สามารถโหลดฐานข้อมูล Supabase: '+error.message,true)}else if(data?.data){try{state=normalizeState(data.data)}catch{state=EMPTY()}}else{
  saveStatus='พร้อมสร้างพื้นที่งาน';
  try{
    const local=localStorage.getItem('ken-affiliate-v4:local');
    if(local){const existing=normalizeState(JSON.parse(local));const populated=(existing.products?.length||0)+(existing.characters?.length||0)+(existing.campaigns?.length||0)+(existing.metrics?.length||0)>0;
      if(populated&&confirm('พบข้อมูลจากโหมดไม่ล็อกอินในเครื่องนี้ ต้องการนำเข้าบัญชีอีเมลของคุณหรือไม่?')){
        state=existing;persist();saveStatus='กำลังย้ายข้อมูลเข้าบัญชี';
      }
    }
  }catch(e){saveStatus='นำเข้าข้อมูลเดิมไม่ได้';showAlert('อ่านข้อมูลเดิมไม่ได้ คุณยังสามารถนำเข้าไฟล์สำรองได้',true)}
}render()}
