function characterPrompt(c){return `CHARACTER MASTER / ${c.name}\nบทบาทและบุคลิก: ${c.persona}\nสไตล์ภาพ: ${c.style||'อิงรูป Master Reference ที่ได้รับอนุญาต'}\nกฎ: ${c.rules||'คงบุคลิกและความต่อเนื่อง ไม่สร้างรีวิวเท็จ'}\nใช้ภาพ Master Reference ที่แนบเป็นแหล่งอ้างอิง หากไม่มีภาพ อย่ารับประกันความเหมือน\nข้อกำหนด: ห้ามสร้างประสบการณ์ใช้งานสินค้าเท็จ ห้ามแสดงตัวเลขที่ไม่ได้มาจากข้อมูลที่ยืนยันแล้ว\nแนววิดีโอ: แนวตั้ง 9:16 สำหรับ Short-form, หลีกเลี่ยงการกล่าวอ้างเกินจริง`}
