 function lines(text,maxWidth,size){ctx.font=`700 ${size}px Arial,sans-serif`;const out=[];let cur='';for(const w of Array.from(text)){if(ctx.measureText(cur+w).width>maxWidth&&cur){out.push(cur);cur=w}else cur+=w}if(cur)out.push(cur);return out.slice(0,5)}
