 if(t<.30){centerText('เรื่องนี้น่าสนใจ!',245,39,'#a4d2d0');centerText(o.hook||name,420,45);centerText('รีวิวจากข้อมูลที่ตรวจแล้ว',750,32,'#71e1c6')}
 else if(t<.68){centerText(name,265,49);centerText(`ราคา ณ เวลาที่ตรวจ: ฿${Number(price).toLocaleString('th-TH')}`,575,40,'#7ff3c4');centerText('ตรวจราคาล่าสุดจากหน้าสินค้า',730,32,'#cdd7e3')}
 else {centerText('สนใจสินค้านี้?',300,62);centerText(name,520,43,'#cce6f3');centerText('เปิดลิงก์ Affiliate ในคำอธิบาย',735,36,'#7ff3c4')}
